#!/bin/sh
# Regenerate compiler/src/runtime_trk.trk from compiler/rt/*.trk.
#
# Every program trackc builds links the runtime written in Track
# (compiler/rt/), so trackc carries the rt modules as Track string literals
# (docs/native.md).
#
#   scripts/embed_runtime.sh          # rewrite the generated file
#   scripts/embed_runtime.sh --check  # fail if it is out of date
set -eu

root=$(cd "$(dirname "$0")/.." && pwd)
out="$root/compiler/src/runtime_trk.trk"
tmp="${out}.tmp.$$"
modules="mem io str vec os/linux os/windows os/macos libc"

{
    echo "// runtime_trk.trk — GENERATED by scripts/embed_runtime.sh from"
    echo "// compiler/rt/*.trk. Do not edit by hand."
    echo ""
    echo "import \"base\";"
    echo ""
    n=0
    for m in $modules; do n=$((n + 1)); done
    echo "fn rt_module_count() -> i64 { return $n; }"
    echo ""
    echo "fn rt_module_name(i: i64) -> i64 {"
    i=0
    for m in $modules; do
        echo "    if i == $i { return \"rt/$m.trk\"; }"
        i=$((i + 1))
    done
    echo "    return \"\";"
    echo "}"
    i=0
    for m in $modules; do
        echo ""
        echo "fn rt_module_source_$i(b: i64) -> i64 {"
        awk '{
            gsub(/\\/, "\\\\")
            gsub(/"/, "\\\"")
            print "    sb_line(b, \"" $0 "\");"
        }' "$root/compiler/rt/$m.trk"
        echo "    return 0;"
        echo "}"
        i=$((i + 1))
    done
    echo ""
    echo "fn rt_module_source(i: i64) -> i64 {"
    echo "    let b = sb_new();"
    i=0
    for m in $modules; do
        echo "    if i == $i { rt_module_source_$i(b); }"
        i=$((i + 1))
    done
    echo "    return sb_text(b);"
    echo "}"
} > "$tmp"

if [ "${1:-}" = "--check" ]; then
    if cmp -s "$tmp" "$out"; then
        rm -f "$tmp"
        echo "runtime_trk.trk is up to date"
        exit 0
    fi
    rm -f "$tmp"
    echo "compiler/src/runtime_trk.trk is stale; run scripts/embed_runtime.sh" >&2
    exit 1
fi
mv "$tmp" "$out"
echo "wrote $out"
